shellCommands.command:
cat > src/__smoke.test.tsx <<'EOF'
import {describe, expect, it} from 'vitest';
import {renderToStaticMarkup} from 'react-dom/server';
import {ThemeProvider} from '@gravity-ui/uikit';
import {App} from './App';

describe('App smoke', () => {
    it('renders first page with 10 rows, selection checkboxes and pagination', () => {
        const html = renderToStaticMarkup(
            <ThemeProvider theme="light">
                <App />
            </ThemeProvider>,
        );
        const tbody = html.match(/<tbody[\s\S]*?<\/tbody>/)?.[0] ?? '';
        const bodyRows = (tbody.match(/<tr/g) ?? []).length;
        const checkboxes = (html.match(/type="checkbox"/g) ?? []).length;
        console.log('RESULT bodyRows', bodyRows, 'checkboxes', checkboxes);
        console.log('RESULT selectedCounter', html.includes('Выбрано строк: 0'));
        console.log('RESULT firstRowName', html.includes('Анна Антонов'));
        console.log('RESULT sortHeaders', (html.match(/role="button"/g) ?? []).length);
        console.log('RESULT paginationPresent', html.includes('g-pagination'));
        expect(bodyRows).toBe(10);
        expect(checkboxes).toBe(11);
        expect(html.includes('Выбрано строк: 0')).toBe(true);
    });
});
EOF
timeout 120 npx vitest run src/__smoke.test.tsx --server.deps.inline=@gravity-ui/uikit 2>&1 | grep -v "npm warn" | grep -E "RESULT|PASS|FAIL|Error|Tests|expected" | head -30; rm -f src/__smoke.test.tsx; echo "temp test removed"

